DROP TABLE IF EXISTS `vw_inventory_summary`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_inventory_summary`  AS SELECT `p`.`product_id` AS `product_id`, `p`.`product_name` AS `product_name`, `p`.`category` AS `category`, `w`.`warehouse_id` AS `warehouse_id`, `w`.`warehouse_name` AS `warehouse_name`, sum(`im`.`quantity_change`) AS `current_stock` FROM ((`inventory_movements` `im` join `products` `p` on(`p`.`product_id` = `im`.`product_id`)) join `warehouses` `w` on(`w`.`warehouse_id` = `im`.`warehouse_id`)) GROUP BY `p`.`product_id`, `p`.`product_name`, `p`.`category`, `w`.`warehouse_id`, `w`.`warehouse_name` ;

