--
-- Structure for view `vw_monthly_sales`
--
DROP TABLE IF EXISTS `vw_monthly_sales`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_monthly_sales`  AS SELECT date_format(`s`.`sale_date`,'%Y-%m') AS `sales_month`, count(0) AS `total_transactions`, sum(`s`.`quantity_sold`) AS `units_sold`, round(sum(`s`.`quantity_sold` * `s`.`unit_price`),2) AS `revenue`, round(sum(`s`.`quantity_sold` * (`s`.`unit_price` - `p`.`unit_cost`)),2) AS `estimated_gross_profit` FROM (`sales` `s` join `products` `p` on(`p`.`product_id` = `s`.`product_id`)) GROUP BY date_format(`s`.`sale_date`,'%Y-%m') ;

