--
-- Structure for view `vw_product_performance`
--
DROP TABLE IF EXISTS `vw_product_performance`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_product_performance`  AS SELECT `p`.`product_id` AS `product_id`, `p`.`product_name` AS `product_name`, `p`.`category` AS `category`, coalesce(sum(`s`.`quantity_sold`),0) AS `units_sold`, round(coalesce(sum(`s`.`quantity_sold` * `s`.`unit_price`),0),2) AS `revenue`, round(coalesce(sum(`s`.`quantity_sold` * (`s`.`unit_price` - `p`.`unit_cost`)),0),2) AS `estimated_gross_profit`, round(100.0 * coalesce(sum(`s`.`quantity_sold` * (`s`.`unit_price` - `p`.`unit_cost`)),0) / nullif(sum(`s`.`quantity_sold` * `s`.`unit_price`),0),2) AS `estimated_profit_margin_pct` FROM (`products` `p` left join `sales` `s` on(`s`.`product_id` = `p`.`product_id`)) GROUP BY `p`.`product_id`, `p`.`product_name`, `p`.`category` ;

