--
-- Structure for view `vw_supplier_performance`
--
DROP TABLE IF EXISTS `vw_supplier_performance`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_supplier_performance`  AS SELECT `s`.`supplier_id` AS `supplier_id`, `s`.`supplier_name` AS `supplier_name`, count(0) AS `total_orders`, sum(case when `po`.`actual_delivery` <= `po`.`expected_delivery` then 1 else 0 end) AS `on_time_orders`, round(100.0 * sum(case when `po`.`actual_delivery` <= `po`.`expected_delivery` then 1 else 0 end) / count(0),2) AS `on_time_delivery_pct`, round(avg(to_days(`po`.`actual_delivery`) - to_days(`po`.`expected_delivery`)),2) AS `avg_days_vs_expected` FROM (`suppliers` `s` join `purchase_orders` `po` on(`po`.`supplier_id` = `s`.`supplier_id`)) WHERE `po`.`actual_delivery` is not null GROUP BY `s`.`supplier_id`, `s`.`supplier_name` ;

